-- BECE BDT Questions - 2024 (40 questions)
INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Pre-Technical Skills: Woodwork (Questions 1-8)
('q_bece_bdt_2024_001', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which of the following is a hand tool used in woodwork?', 'multiple_choice', '["A. Lathe machine", "B. Jack plane", "C. Drilling machine", "D. Band saw"]', 'B', 'A jack plane is a hand tool used for smoothing and shaping wood. Lathe machines, drilling machines, and band saws are power tools.', 'easy', 1, 1),
('q_bece_bdt_2024_002', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The process of joining two pieces of wood using glue is called:', 'multiple_choice', '["A. Welding", "B. Soldering", "C. Gluing/Bonding", "D. Riveting"]', 'C', 'Gluing or bonding is the process of joining wood pieces using adhesive. Welding and soldering are for metals.', 'easy', 1, 2),
('q_bece_bdt_2024_003', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which type of wood is obtained from cone-bearing trees?', 'multiple_choice', '["A. Hardwood", "B. Softwood", "C. Plywood", "D. Chipboard"]', 'B', 'Softwood comes from coniferous (cone-bearing) trees like pine and cedar. Hardwood comes from deciduous trees.', 'medium', 1, 3),
('q_bece_bdt_2024_004', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The tool used to measure and mark 90-degree angles in woodwork is:', 'multiple_choice', '["A. Marking gauge", "B. Try square", "C. Sliding bevel", "D. Compass"]', 'B', 'A try square is used to mark and check right angles (90 degrees) in woodwork. A sliding bevel is for other angles.', 'easy', 1, 4),
('q_bece_bdt_2024_005', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Sandpaper is used for:', 'multiple_choice', '["A. Cutting wood", "B. Smoothing surfaces", "C. Joining wood", "D. Measuring wood"]', 'B', 'Sandpaper (abrasive paper) is used to smooth wood surfaces and remove small imperfections.', 'easy', 1, 5),
('q_bece_bdt_2024_006', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'A mortise joint is made using a:', 'multiple_choice', '["A. Hammer and nail", "B. Chisel and mallet", "C. Screwdriver", "D. Drill only"]', 'B', 'A mortise is a rectangular hole cut into wood using a chisel and mallet, designed to receive a tenon.', 'medium', 1, 6),
('q_bece_bdt_2024_007', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The process of applying finish to protect wood is called:', 'multiple_choice', '["A. Painting", "B. Seasoning", "C. Finishing", "D. Sanding"]', 'C', 'Finishing is the process of applying protective coatings like varnish, lacquer, or paint to wood surfaces.', 'easy', 1, 7),
('q_bece_bdt_2024_008', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which of the following is a type of wood joint?', 'multiple_choice', '["A. Butt joint", "B. Welded joint", "C. Soldered joint", "D. Riveted joint"]', 'A', 'A butt joint is the simplest wood joint where two pieces meet end-to-end or edge-to-edge. The others are metal joints.', 'easy', 1, 8),

-- Pre-Technical Skills: Metalwork (Questions 9-15)
('q_bece_bdt_2024_009', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which tool is used to hold metal firmly while working on it?', 'multiple_choice', '["A. Hammer", "B. Vice", "C. File", "D. Hacksaw"]', 'B', 'A vice (or vise) is a clamping device used to hold metal or other materials firmly in place while working.', 'easy', 1, 9),
('q_bece_bdt_2024_010', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'A hacksaw is used for:', 'multiple_choice', '["A. Smoothing metal", "B. Cutting metal", "C. Bending metal", "D. Welding metal"]', 'B', 'A hacksaw is a hand tool with a fine-toothed blade used for cutting metal and other materials.', 'easy', 1, 10),
('q_bece_bdt_2024_011', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The process of joining metals using heat is called:', 'multiple_choice', '["A. Gluing", "B. Nailing", "C. Welding", "D. Screwing"]', 'C', 'Welding is the process of joining metals by melting them together, usually with additional filler material.', 'easy', 1, 11),
('q_bece_bdt_2024_012', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Files are used in metalwork for:', 'multiple_choice', '["A. Cutting large pieces", "B. Smoothing and shaping", "C. Welding", "D. Measuring"]', 'B', 'Files are hand tools used for smoothing, shaping, and removing small amounts of material from metal surfaces.', 'easy', 1, 12),
('q_bece_bdt_2024_013', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which of the following is a ferrous metal?', 'multiple_choice', '["A. Aluminium", "B. Copper", "C. Iron", "D. Brass"]', 'C', 'Iron is a ferrous metal (contains iron). Aluminium, copper, and brass are non-ferrous metals.', 'medium', 1, 13),
('q_bece_bdt_2024_014', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The protective equipment worn when welding includes:', 'multiple_choice', '["A. Sun glasses", "B. Reading glasses", "C. Welding goggles/helmet", "D. Regular eyeglasses"]', 'C', 'Welding goggles or helmets with special darkened lenses protect eyes from the intense light and sparks during welding.', 'easy', 1, 14),
('q_bece_bdt_2024_015', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'A centre punch is used to:', 'multiple_choice', '["A. Cut metal", "B. Mark a starting point for drilling", "C. Measure thickness", "D. Bend metal"]', 'B', 'A centre punch is used to make a small indentation to mark the starting point for drilling, preventing the drill from slipping.', 'medium', 1, 15),

-- Home Economics: Foods and Nutrition (Questions 16-23)
('q_bece_bdt_2024_016', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which nutrient is the body''s main source of energy?', 'multiple_choice', '["A. Proteins", "B. Carbohydrates", "C. Vitamins", "D. Minerals"]', 'B', 'Carbohydrates are the body''s primary source of energy. They are broken down into glucose for immediate energy.', 'easy', 1, 16),
('q_bece_bdt_2024_017', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Proteins are essential for:', 'multiple_choice', '["A. Energy only", "B. Growth and repair of body tissues", "C. Strong bones only", "D. Vision only"]', 'B', 'Proteins are essential for growth, repair, and maintenance of body tissues, as well as making enzymes and hormones.', 'easy', 1, 17),
('q_bece_bdt_2024_018', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which vitamin is obtained from sunlight?', 'multiple_choice', '["A. Vitamin A", "B. Vitamin B", "C. Vitamin C", "D. Vitamin D"]', 'D', 'Vitamin D is synthesized by the body when the skin is exposed to sunlight. It helps in calcium absorption.', 'easy', 1, 18),
('q_bece_bdt_2024_019', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Iron deficiency leads to:', 'multiple_choice', '["A. Scurvy", "B. Anaemia", "C. Rickets", "D. Goitre"]', 'B', 'Iron deficiency causes anaemia, characterized by reduced red blood cells and symptoms like fatigue and weakness.', 'medium', 1, 19),
('q_bece_bdt_2024_020', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which cooking method preserves the most nutrients?', 'multiple_choice', '["A. Deep frying", "B. Boiling in excess water", "C. Steaming", "D. Roasting at high heat"]', 'C', 'Steaming preserves the most nutrients because food does not come in direct contact with water and cooks at lower temperatures.', 'medium', 1, 20),
('q_bece_bdt_2024_021', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Food contamination can be prevented by:', 'multiple_choice', '["A. Leaving food uncovered", "B. Proper hand washing before cooking", "C. Using the same cutting board for raw meat and vegetables", "D. Storing cooked and raw foods together"]', 'B', 'Proper hand washing is one of the most effective ways to prevent food contamination and foodborne illnesses.', 'easy', 1, 21),
('q_bece_bdt_2024_022', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which food group provides calcium for strong bones?', 'multiple_choice', '["A. Fruits", "B. Dairy products", "C. Oils", "D. Cereals"]', 'B', 'Dairy products like milk, cheese, and yogurt are rich sources of calcium needed for strong bones and teeth.', 'easy', 1, 22),
('q_bece_bdt_2024_023', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The correct temperature for storing frozen food is:', 'multiple_choice', '["A. 0°C", "B. -18°C or below", "C. 4°C", "D. 10°C"]', 'B', 'Frozen foods should be stored at -18°C (0°F) or below to prevent bacterial growth and maintain quality.', 'medium', 1, 23),

-- Home Economics: Clothing and Textiles (Questions 24-30)
('q_bece_bdt_2024_024', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Cotton is obtained from:', 'multiple_choice', '["A. Animals", "B. Plants", "C. Chemicals", "D. Minerals"]', 'B', 'Cotton is a natural fiber obtained from the cotton plant (specifically the seed pods or bolls).', 'easy', 1, 24),
('q_bece_bdt_2024_025', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which fiber comes from silkworms?', 'multiple_choice', '["A. Wool", "B. Silk", "C. Nylon", "D. Linen"]', 'B', 'Silk is a natural protein fiber produced by silkworms when making their cocoons.', 'easy', 1, 25),
('q_bece_bdt_2024_026', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'A thimble is used when sewing to:', 'multiple_choice', '["A. Cut thread", "B. Protect the finger", "C. Hold fabric", "D. Measure fabric"]', 'B', 'A thimble is worn on the finger to protect it from being pricked by the needle when sewing.', 'easy', 1, 26),
('q_bece_bdt_2024_027', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The running stitch is used for:', 'multiple_choice', '["A. Decorative purposes only", "B. Joining fabrics together temporarily or permanently", "C. Making buttonholes", "D. Hemming only"]', 'B', 'The running stitch is a basic stitch used to join fabrics together, either temporarily (basting) or permanently.', 'easy', 1, 27),
('q_bece_bdt_2024_028', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Polyester is a type of:', 'multiple_choice', '["A. Natural fiber", "B. Synthetic fiber", "C. Animal fiber", "D. Vegetable fiber"]', 'B', 'Polyester is a synthetic (man-made) fiber produced from petroleum-based chemicals.', 'easy', 1, 28),
('q_bece_bdt_2024_029', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Before cutting fabric, you should:', 'multiple_choice', '["A. Iron it first", "B. Wash and dry it", "C. Pre-shrink or prepare it", "D. All of the above"]', 'D', 'Before cutting, fabric should be washed (to pre-shrink), dried, and ironed to ensure accurate cutting and prevent shrinkage later.', 'medium', 1, 29),
('q_bece_bdt_2024_030', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The selvage of a fabric is the:', 'multiple_choice', '["A. Center of the fabric", "B. Finished edges running lengthwise", "C. Cut edges", "D. Pattern on the fabric"]', 'B', 'The selvage is the self-finished edge of the fabric running lengthwise, preventing unraveling.', 'medium', 1, 30),

-- Visual Arts (Questions 31-40)
('q_bece_bdt_2024_031', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The primary colors are:', 'multiple_choice', '["A. Orange, green, purple", "B. Red, yellow, blue", "C. Black, white, gray", "D. Pink, brown, violet"]', 'B', 'The primary colors in art are red, yellow, and blue. They cannot be made by mixing other colors.', 'easy', 1, 31),
('q_bece_bdt_2024_032', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Mixing red and yellow produces:', 'multiple_choice', '["A. Purple", "B. Green", "C. Orange", "D. Brown"]', 'C', 'Red + Yellow = Orange. This is one of the three secondary colors.', 'easy', 1, 32),
('q_bece_bdt_2024_033', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which element of art refers to the lightness or darkness of a color?', 'multiple_choice', '["A. Hue", "B. Value", "C. Intensity", "D. Texture"]', 'B', 'Value refers to the lightness or darkness of a color. Adding white creates tints, adding black creates shades.', 'medium', 1, 33),
('q_bece_bdt_2024_034', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Clay is used in which type of art?', 'multiple_choice', '["A. Painting", "B. Pottery/Ceramics", "C. Photography", "D. Typography"]', 'B', 'Clay is the primary material used in pottery and ceramics to create functional and decorative objects.', 'easy', 1, 34),
('q_bece_bdt_2024_035', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Batik is a method of:', 'multiple_choice', '["A. Weaving", "B. Dyeing fabric using wax resist", "C. Knitting", "D. Painting on canvas"]', 'B', 'Batik is a wax-resist dyeing technique where wax is applied to fabric to prevent dye from coloring certain areas.', 'medium', 1, 35),
('q_bece_bdt_2024_036', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'The process of creating images by carving on a surface is called:', 'multiple_choice', '["A. Painting", "B. Sculpture", "C. Printmaking", "D. Photography"]', 'C', 'Printmaking involves carving an image on a surface (wood, linoleum, metal) and then transferring it to paper.', 'medium', 1, 36),
('q_bece_bdt_2024_037', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Kente cloth is a traditional Ghanaian:', 'multiple_choice', '["A. Pottery style", "B. Woven fabric", "C. Painting technique", "D. Sculpture form"]', 'B', 'Kente is a traditional Ghanaian woven fabric known for its colorful patterns and cultural significance.', 'easy', 1, 37),
('q_bece_bdt_2024_038', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Which tool is used for drawing straight lines in technical drawing?', 'multiple_choice', '["A. Compass", "B. T-square/Ruler", "C. Protractor", "D. French curve"]', 'B', 'A T-square or ruler is used to draw straight horizontal and vertical lines in technical drawing.', 'easy', 1, 38),
('q_bece_bdt_2024_039', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'Balance in art refers to:', 'multiple_choice', '["A. The size of the artwork", "B. Distribution of visual weight", "C. The colors used", "D. The medium used"]', 'B', 'Balance in art refers to the distribution of visual weight in a composition, creating a sense of stability.', 'medium', 1, 39),
('q_bece_bdt_2024_040', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2024_1', 'An Adinkra symbol represents:', 'multiple_choice', '["A. Nothing specific", "B. Concepts, proverbs, or values", "C. Only animals", "D. Only geometric shapes"]', 'B', 'Adinkra symbols are traditional Ghanaian symbols that represent concepts, proverbs, historical events, or philosophical ideas.', 'easy', 1, 40),

-- BECE BDT Questions - 2023 (40 questions)
-- Pre-Technical Skills (Questions 1-12)
('q_bece_bdt_2023_001', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Which of the following is NOT a woodworking tool?', 'multiple_choice', '["A. Claw hammer", "B. Tenon saw", "C. Soldering iron", "D. Wood chisel"]', 'C', 'A soldering iron is used for metalwork (joining metals), not woodwork. The others are all woodworking tools.', 'easy', 1, 1),
('q_bece_bdt_2023_002', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The tenon saw is used for:', 'multiple_choice', '["A. Rough cutting", "B. Cutting curves", "C. Fine, accurate cutting", "D. Cutting metal"]', 'C', 'A tenon saw has fine teeth and is used for making accurate, fine cuts in wood, especially for joints.', 'easy', 1, 2),
('q_bece_bdt_2023_003', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Seasoning of wood is done to:', 'multiple_choice', '["A. Make it colorful", "B. Remove moisture content", "C. Make it heavier", "D. Add flavor"]', 'B', 'Seasoning removes moisture from wood to prevent warping, cracking, and decay, making it suitable for use.', 'medium', 1, 3),
('q_bece_bdt_2023_004', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Which joint is used to join wood at right angles?', 'multiple_choice', '["A. Lap joint", "B. Dovetail joint", "C. Corner joint", "D. Butt joint"]', 'C', 'A corner joint (or mitre joint) is commonly used to join two pieces of wood at right angles (90 degrees).', 'easy', 1, 4),
('q_bece_bdt_2023_005', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The claw hammer is used for:', 'multiple_choice', '["A. Cutting wood", "B. Driving and removing nails", "C. Planing wood", "D. Drilling holes"]', 'B', 'A claw hammer has a head for driving nails and a claw for removing them.', 'easy', 1, 5),
('q_bece_bdt_2023_006', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Brass is an alloy of:', 'multiple_choice', '["A. Iron and carbon", "B. Copper and zinc", "C. Aluminium and copper", "D. Tin and lead"]', 'B', 'Brass is an alloy made from copper and zinc. It is yellowish and often used for decorative items.', 'medium', 1, 6),
('q_bece_bdt_2023_007', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The process of removing rust from metal is called:', 'multiple_choice', '["A. Painting", "B. Rusting", "C. De-rusting/Cleaning", "D. Welding"]', 'C', 'De-rusting or cleaning removes rust from metal surfaces using wire brushes, sandpaper, or chemical solutions.', 'easy', 1, 7),
('q_bece_bdt_2023_008', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Which of the following protects metal from rusting?', 'multiple_choice', '["A. Water", "B. Salt", "C. Paint or oil coating", "D. Acid"]', 'C', 'Paint or oil creates a protective barrier that prevents moisture and oxygen from reaching the metal surface.', 'easy', 1, 8),
('q_bece_bdt_2023_009', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'A screwdriver is classified as a:', 'multiple_choice', '["A. Cutting tool", "B. Driving tool", "C. Measuring tool", "D. Holding tool"]', 'B', 'A screwdriver is a driving tool used to insert and remove screws.', 'easy', 1, 9),
('q_bece_bdt_2023_010', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The ball peen hammer is primarily used in:', 'multiple_choice', '["A. Woodwork", "B. Metalwork", "C. Sewing", "D. Cooking"]', 'B', 'The ball peen hammer is a metalworking tool with a rounded end used for shaping metal and setting rivets.', 'easy', 1, 10),
('q_bece_bdt_2023_011', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Plywood is made by:', 'multiple_choice', '["A. Melting wood", "B. Gluing thin layers of wood together", "C. Pressing sawdust", "D. Carving solid wood"]', 'B', 'Plywood is manufactured by gluing thin layers (veneers) of wood together with alternating grain directions.', 'medium', 1, 11),
('q_bece_bdt_2023_012', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Which measuring tool is used to measure the diameter of round objects?', 'multiple_choice', '["A. Ruler", "B. Caliper", "C. Protractor", "D. T-square"]', 'B', 'A caliper (vernier or dial) is used to measure the diameter, thickness, and depth of objects accurately.', 'medium', 1, 12),

-- Home Economics (Questions 13-26)
('q_bece_bdt_2023_013', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Kwashiorkor is caused by deficiency of:', 'multiple_choice', '["A. Carbohydrates", "B. Proteins", "C. Fats", "D. Water"]', 'B', 'Kwashiorkor is a severe form of malnutrition caused by protein deficiency, common in children.', 'medium', 1, 13),
('q_bece_bdt_2023_014', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Vitamin C deficiency causes:', 'multiple_choice', '["A. Night blindness", "B. Scurvy", "C. Rickets", "D. Beriberi"]', 'B', 'Scurvy is caused by Vitamin C deficiency, leading to weakness, gum problems, and poor wound healing.', 'easy', 1, 14),
('q_bece_bdt_2023_015', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Which of the following is a protein-rich food?', 'multiple_choice', '["A. Rice", "B. Beans", "C. Cassava", "D. Plantain"]', 'B', 'Beans are legumes rich in protein. Rice, cassava, and plantain are primarily carbohydrate sources.', 'easy', 1, 15),
('q_bece_bdt_2023_016', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Food preservation by drying works because:', 'multiple_choice', '["A. It adds chemicals", "B. It removes moisture needed by microbes", "C. It cooks the food", "D. It adds salt"]', 'B', 'Drying removes moisture from food, preventing the growth of bacteria, molds, and yeasts that need water to survive.', 'medium', 1, 16),
('q_bece_bdt_2023_017', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The correct way to thaw frozen food is:', 'multiple_choice', '["A. Leave at room temperature all day", "B. In the refrigerator", "C. In hot water", "D. In direct sunlight"]', 'B', 'Thawing in the refrigerator is safest as it keeps food at a safe temperature while defrosting gradually.', 'easy', 1, 17),
('q_bece_bdt_2023_018', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Which fiber is known for its ability to absorb water?', 'multiple_choice', '["A. Polyester", "B. Nylon", "C. Cotton", "D. Acrylic"]', 'C', 'Cotton is a natural fiber with excellent absorbency, making it comfortable for clothing in hot weather.', 'easy', 1, 18),
('q_bece_bdt_2023_019', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Wool comes from:', 'multiple_choice', '["A. Plants", "B. Sheep", "C. Silkworms", "D. Petroleum"]', 'B', 'Wool is a natural animal fiber obtained from sheep and some other animals like goats (cashmere).', 'easy', 1, 19),
('q_bece_bdt_2023_020', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The backstitch is used for:', 'multiple_choice', '["A. Temporary stitching", "B. Strong, permanent seams", "C. Decorative purposes only", "D. Gathering fabric"]', 'B', 'The backstitch is a strong, permanent stitch used for seams that need to withstand stress.', 'medium', 1, 20),
('q_bece_bdt_2023_021', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Which stitch is used for hemming?', 'multiple_choice', '["A. Running stitch", "B. Hemming stitch", "C. Backstitch", "D. Cross stitch"]', 'B', 'The hemming stitch (or slip stitch) is specifically designed for creating neat, invisible hems on garments.', 'easy', 1, 21),
('q_bece_bdt_2023_022', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'A seam allowance is:', 'multiple_choice', '["A. The space between buttons", "B. Extra fabric for stitching", "C. The pattern pieces", "D. The hemline"]', 'B', 'Seam allowance is the extra fabric between the cutting line and the stitching line, typically 1.5 cm.', 'medium', 1, 22),
('q_bece_bdt_2023_023', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Tie and dye is a method of:', 'multiple_choice', '["A. Weaving", "B. Printing patterns on fabric", "C. Creating patterns using resist dyeing", "D. Embroidery"]', 'C', 'Tie and dye involves tying fabric in various ways to resist dye penetration, creating patterns.', 'easy', 1, 23),
('q_bece_bdt_2023_024', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'When ironing, delicate fabrics should be ironed at:', 'multiple_choice', '["A. High temperature", "B. Low temperature", "C. Medium temperature", "D. Maximum heat"]', 'B', 'Delicate fabrics like silk and synthetic materials should be ironed at low temperatures to prevent damage.', 'easy', 1, 24),
('q_bece_bdt_2023_025', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'A balanced diet contains:', 'multiple_choice', '["A. Only proteins", "B. All classes of food in right proportions", "C. Only carbohydrates", "D. Only vitamins"]', 'B', 'A balanced diet contains all nutrients (carbohydrates, proteins, fats, vitamins, minerals, water) in appropriate amounts.', 'easy', 1, 25),
('q_bece_bdt_2023_026', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The danger zone for food temperature is:', 'multiple_choice', '["A. Below 0°C", "B. 5°C to 60°C", "C. Above 100°C", "D. Below -18°C"]', 'B', 'The temperature danger zone (5°C to 60°C) is where bacteria multiply rapidly, making food unsafe.', 'medium', 1, 26),

-- Visual Arts (Questions 27-40)
('q_bece_bdt_2023_027', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Secondary colors are made by mixing:', 'multiple_choice', '["A. Black and white", "B. Two primary colors", "C. Three primary colors", "D. Primary and secondary colors"]', 'B', 'Secondary colors (orange, green, purple) are made by mixing two primary colors together.', 'easy', 1, 27),
('q_bece_bdt_2023_028', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Blue and yellow mixed together produce:', 'multiple_choice', '["A. Orange", "B. Purple", "C. Green", "D. Brown"]', 'C', 'Blue + Yellow = Green. This is one of the three secondary colors.', 'easy', 1, 28),
('q_bece_bdt_2023_029', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Adding white to a color creates a:', 'multiple_choice', '["A. Shade", "B. Tint", "C. Tone", "D. Hue"]', 'B', 'A tint is created by adding white to a color, making it lighter. A shade is created by adding black.', 'easy', 1, 29),
('q_bece_bdt_2023_030', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Sculpture can be created using all EXCEPT:', 'multiple_choice', '["A. Wood", "B. Clay", "C. Stone", "D. Sound"]', 'D', 'Sculpture is a three-dimensional art form created from physical materials like wood, clay, stone, or metal, not sound.', 'easy', 1, 30),
('q_bece_bdt_2023_031', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Weaving involves interlacing:', 'multiple_choice', '["A. Colors", "B. Warp and weft threads", "C. Paints", "D. Papers"]', 'B', 'Weaving creates fabric by interlacing vertical warp threads with horizontal weft threads.', 'easy', 1, 31),
('q_bece_bdt_2023_032', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'A compass is used in art for:', 'multiple_choice', '["A. Drawing straight lines", "B. Drawing circles and arcs", "C. Measuring angles", "D. Erasing mistakes"]', 'B', 'A compass is a drawing tool used to create circles and arcs of various sizes.', 'easy', 1, 32),
('q_bece_bdt_2023_033', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Warm colors include:', 'multiple_choice', '["A. Blue, green, purple", "B. Red, orange, yellow", "C. Black, white, gray", "D. Brown, beige, cream"]', 'B', 'Warm colors (red, orange, yellow) evoke warmth and energy. Cool colors are blue, green, and purple.', 'easy', 1, 33),
('q_bece_bdt_2023_034', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'In technical drawing, a front view is also called:', 'multiple_choice', '["A. Plan", "B. Elevation", "C. Isometric", "D. Perspective"]', 'B', 'An elevation is the front (or side) view of an object in technical drawing, showing height and width.', 'medium', 1, 34),
('q_bece_bdt_2023_035', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Mosaic art is made by:', 'multiple_choice', '["A. Painting on canvas", "B. Arranging small pieces of material to form patterns", "C. Sculpting clay", "D. Weaving threads"]', 'B', 'Mosaic art involves arranging small pieces (tesserae) of glass, stone, or tile to create images or patterns.', 'easy', 1, 35),
('q_bece_bdt_2023_036', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The element of art that refers to how surfaces feel or look is:', 'multiple_choice', '["A. Color", "B. Line", "C. Texture", "D. Shape"]', 'C', 'Texture describes the surface quality of an object - how it feels or appears to feel (smooth, rough, etc.).', 'easy', 1, 36),
('q_bece_bdt_2023_037', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Symmetrical balance means:', 'multiple_choice', '["A. One side is different from the other", "B. Both sides are mirror images", "C. No balance at all", "D. Random arrangement"]', 'B', 'Symmetrical balance (formal balance) occurs when both sides of a composition are mirror images of each other.', 'easy', 1, 37),
('q_bece_bdt_2023_038', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Calabash decoration is a traditional art of:', 'multiple_choice', '["A. Europe", "B. Ghana/Africa", "C. Asia", "D. Australia"]', 'B', 'Calabash (gourd) decoration is a traditional art form in Ghana and other African countries.', 'easy', 1, 38),
('q_bece_bdt_2023_039', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'The principle of art that creates visual interest is:', 'multiple_choice', '["A. Boredom", "B. Variety", "C. Uniformity", "D. Sameness"]', 'B', 'Variety adds visual interest by using different elements (colors, shapes, textures) in an artwork.', 'easy', 1, 39),
('q_bece_bdt_2023_040', 'subj_bece_bdt', 'exam_bece', 'paper_bece_1', 'pp_bece_bdt_2023_1', 'Appliqué is a technique of:', 'multiple_choice', '["A. Painting", "B. Attaching fabric pieces onto a background", "C. Sculpting", "D. Drawing"]', 'B', 'Appliqué is a textile technique where pieces of fabric are sewn onto a larger background to create designs.', 'medium', 1, 40);
